// ---- MyFit Coach (AI) ----
S('nav.coach', 'MyFit Coach', 'Coach MyFit', 'مدرب MyFit', 'الكوتش ديال MyFit'); S('hub.coach', 'Ask anything about food', 'Posez vos questions', 'اسألي عن أي شيء في الأكل', 'سولي على أي حاجة فالماكلة');
S('coach.title', 'MyFit Coach', 'Coach MyFit', 'مدرب MyFit', 'الكوتش ديال MyFit');
S('coach.cardTitle', 'Ask MyFit Coach', 'Demandez au coach', 'اسألي المدرب', 'سولي الكوتش');
S('coach.cardText', 'Meals, recipes, sugar, walking… get a quick answer.', 'Repas, recettes, sucre, marche… une réponse rapide.', 'وجبات، وصفات، سكر، مشي… جواب سريع.', 'الماكلة، الوصفات، السكر، التمشية… جواب دغيا.');
S('coach.introTitle', 'Your personal food coach', 'Votre coach alimentaire', 'مدربك الغذائي الشخصي', 'الكوتش ديالك فالماكلة');
S('coach.introText', 'Ask questions about meals, portions, recipes, sugar, water or walking. The coach uses your MyFit data to give practical, kind advice.', 'Posez vos questions sur les repas, portions, recettes, sucre, eau ou marche. Le coach utilise vos données MyFit pour des conseils pratiques et bienveillants.', 'اسألي عن الوجبات والحصص والوصفات والسكر والماء والمشي. يستخدم المدرب بياناتك في MyFit ليقدم نصائح عملية ولطيفة.', 'سولي على الماكلة، الكميات، الوصفات، السكر، الما ولا التمشية. الكوتش كيستعمل المعطيات ديالك ف MyFit باش يعطيك نصائح عملية.');
S('coach.privacyTitle', 'Before you start', 'Avant de commencer', 'قبل أن تبدئي', 'قبل ما تبداي');
S('coach.p1', 'The coach is an AI (Groq, Llama model). It can make mistakes; check important information.', 'Le coach est une IA (Groq, modèle Llama). Elle peut se tromper ; vérifiez les informations importantes.', 'المدرب ذكاء اصطناعي (Groq، نموذج Llama). قد يخطئ؛ تحققي من المعلومات المهمة.', 'الكوتش ذكاء اصطناعي (Groq، موديل Llama). يقدر يغلط، تأكدي من المعلومات المهمة.');
S('coach.p2', 'Your question and a summary of your MyFit data (profile basics, today’s meals, water, walking, targets) are sent to Groq to write the answer. Free-text health notes are never sent.', 'Votre question et un résumé de vos données MyFit (profil, repas du jour, eau, marche, objectifs) sont envoyés à Groq pour rédiger la réponse. Les notes de santé libres ne sont jamais envoyées.', 'يرسل سؤالك وملخص لبياناتك (الملف، وجبات اليوم، الماء، المشي، الأهداف) إلى Groq لكتابة الجواب. لا ترسل ملاحظاتك الصحية الحرة أبدا.', 'السؤال ديالك وملخص ديال المعطيات (البروفيل، ماكلة اليوم، الما، التمشية، الأهداف) كيتصيفطو ل Groq باش يكتب الجواب. الملاحظات الصحية ما كتصيفطش.');
S('coach.p3', 'It is not a doctor: no diagnosis, medication or medical diets.', 'Ce n’est pas un médecin : pas de diagnostic, de médicaments ni de régimes médicaux.', 'ليس طبيبا: لا تشخيص ولا أدوية ولا حميات طبية.', 'ماشي طبيب: لا تشخيص، لا دوا، لا ريجيم طبي.');
S('coach.p4', 'Your conversation is saved privately in your account. You can delete it or turn the coach off in Privacy.', 'La conversation est enregistrée en privé dans votre compte. Vous pouvez la supprimer ou désactiver le coach dans Confidentialité.', 'تحفظ المحادثة بشكل خاص في حسابك، ويمكنك حذفها أو إيقاف المدرب من الخصوصية.', 'المحادثة كتتسجل فالحساب ديالك بوحدك. تقدري تمسحيها ولا توقفي الكوتش من الخصوصية.');
S('coach.agree', 'I understand — start', 'J’ai compris — commencer', 'فهمت — ابدئي', 'فهمت — يلاه نبداو');
S('coach.hello', 'Hi {name}! How can I help?', 'Bonjour {name} ! Comment puis-je aider ?', 'مرحبا {name}! كيف أساعدك؟', 'سلام {name}! كيفاش نعاونك؟');
S('coach.helloText', 'Ask a question below or tap a suggestion.', 'Posez une question ou touchez une suggestion.', 'اكتبي سؤالا أو اختاري اقتراحا.', 'كتبي سؤال ولا ختاري واحد من الاقتراحات.');
S('coach.placeholder', 'Ask about food, meals, walking…', 'Une question sur les repas, la marche…', 'اسألي عن الأكل والوجبات والمشي…', 'سولي على الماكلة، التمشية…');
S('coach.send', 'Send', 'Envoyer', 'إرسال', 'صيفط');
S('coach.clear', 'Delete conversation', 'Supprimer la conversation', 'حذف المحادثة', 'مسح المحادثة'); S('coach.cleared', 'Conversation deleted', 'Conversation supprimée', 'تم حذف المحادثة', 'تمسحات المحادثة');
S('coach.disclaimer', 'AI answers can be wrong and are not medical advice.', 'Les réponses de l’IA peuvent être fausses et ne sont pas des conseils médicaux.', 'قد تخطئ إجابات الذكاء الاصطناعي، وهي ليست نصيحة طبية.', 'الأجوبة ديال الذكاء الاصطناعي تقدر تغلط، وماشي نصيحة طبية.');
S('coach.pushLink', 'Daily message on your phone', 'Message quotidien sur le téléphone', 'رسالة يومية على الهاتف', 'ميساج كل نهار فالتيليفون');
S('coach.needOnline', 'The coach needs the online account (Supabase). It is not available in device mode.', 'Le coach nécessite le compte en ligne (Supabase). Indisponible en mode appareil.', 'يحتاج المدرب إلى الحساب على الإنترنت (Supabase)، وهو غير متاح في وضع الجهاز.', 'الكوتش خاصو الحساب أونلاين (Supabase)، ما خدامش ف وضع الجهاز.');
S('coach.privacyShort', 'When the coach is on, your questions and a summary of your MyFit data are sent to Groq (Llama model) to write answers.', 'Quand le coach est activé, vos questions et un résumé de vos données sont envoyés à Groq (modèle Llama).', 'عند تفعيل المدرب، ترسل أسئلتك وملخص بياناتك إلى Groq (نموذج Llama).', 'ملي الكوتش خدام، الأسئلة وملخص المعطيات ديالك كيتصيفطو ل Groq (موديل Llama).');
S('coach.revoke', 'Turn off the coach and delete the conversation', 'Désactiver le coach et supprimer la conversation', 'إيقاف المدرب وحذف المحادثة', 'وقف الكوتش ومسح المحادثة');
S('coach.notEnabled', 'The coach is off.', 'Le coach est désactivé.', 'المدرب غير مفعل.', 'الكوتش مطفي.');
S('coach.err.not_signed_in', 'Please log in again.', 'Veuillez vous reconnecter.', 'يرجى تسجيل الدخول من جديد.', 'عاودي دخلي للحساب.');
S('coach.err.coach_not_configured', 'The coach is not set up yet (missing Groq API key on the server).', 'Le coach n’est pas encore configuré (clé API Groq manquante sur le serveur).', 'المدرب غير مفعل بعد (مفتاح Groq غير موجود في الخادم).', 'الكوتش مازال ما تفعلش (الساروت ديال Groq ناقص فالسيرفر).');
S('coach.err.database_not_configured', 'The online database is not configured.', 'La base en ligne n’est pas configurée.', 'قاعدة البيانات غير مهيأة.', 'قاعدة البيانات ما مفعلاش.');
S('coach.err.consent_required', 'Please accept the coach terms first.', 'Veuillez d’abord accepter les conditions du coach.', 'يرجى قبول شروط المدرب أولا.', 'قبلي الشروط ديال الكوتش أولا.');
S('coach.err.daily_limit', 'You reached today’s limit of questions. Come back tomorrow!', 'Limite de questions du jour atteinte. Revenez demain !', 'وصلت إلى حد الأسئلة اليوم. عودي غدا!', 'وصلتي للحد ديال الأسئلة اليوم. رجعي غدا!');
S('coach.err.busy', 'The coach is busy right now. Try again in a minute.', 'Le coach est occupé. Réessayez dans une minute.', 'المدرب مشغول الآن. حاولي بعد دقيقة.', 'الكوتش مشغول دابا. عاودي من بعد دقيقة.');
S('coach.err.bad_message', 'Message is empty or too long.', 'Message vide ou trop long.', 'الرسالة فارغة أو طويلة جدا.', 'الميساج خاوي ولا طويل بزاف.');
S('coach.err.coach_error', 'Something went wrong. Please try again.', 'Une erreur est survenue. Réessayez.', 'حدث خطأ. حاولي مجددا.', 'وقع شي مشكل. عاودي.');
S('push.title', 'Coach messages on your phone', 'Messages du coach sur le téléphone', 'رسائل المدرب على الهاتف', 'ميساجات الكوتش فالتيليفون');
S('push.text', 'Every morning, MyFit Coach sends one short, personal tip based on yesterday (meals, water, walking) — even when the app is closed.', 'Chaque matin, le coach envoie un court conseil personnalisé basé sur la veille (repas, eau, marche) — même app fermée.', 'كل صباح يرسل المدرب نصيحة قصيرة مبنية على يوم أمس (الوجبات، الماء، المشي) حتى والتطبيق مغلق.', 'كل صباح الكوتش كيصيفط نصيحة صغيرة على حساب البارح (الماكلة، الما، التمشية)، حتى ملي تكون الآپ مسدودة.');
S('push.toggle', 'Send me the daily coach message', 'M’envoyer le message quotidien', 'أرسل لي رسالة المدرب اليومية', 'صيفط ليا الميساج ديال كل نهار');
S('push.enabled', 'Daily coach messages are on', 'Messages quotidiens activés', 'تم تفعيل الرسائل اليومية', 'الميساجات ديال كل نهار تفعلو');
S('push.noConsent', 'Until you start the coach, the message is a general tip (your data is not used).', 'Tant que le coach n’est pas activé, le message est un conseil général (vos données ne sont pas utilisées).', 'قبل تفعيل المدرب تكون الرسالة نصيحة عامة دون استخدام بياناتك.', 'حتى تفعلي الكوتش، الميساج غادي يكون نصيحة عامة بلا المعطيات ديالك.');
S('push.unsupported', 'This browser cannot receive push messages.', 'Ce navigateur ne peut pas recevoir de notifications push.', 'هذا المتصفح لا يستقبل الإشعارات.', 'هاد المتصفح ما كيستقبلش الإشعارات.');
S('push.ios', 'iPhone: first tap Share → “Add to Home Screen”, open MyFit from the home screen, then turn this on.', 'iPhone : touchez Partager → « Sur l’écran d’accueil », ouvrez MyFit depuis l’écran d’accueil, puis activez.', 'آيفون: اضغطي مشاركة ← «إضافة إلى الشاشة الرئيسية»، افتحي MyFit من الشاشة الرئيسية ثم فعّلي.', 'آيفون: ضغطي Partager ← «Sur l’écran d’accueil»، حلي MyFit من الشاشة ومن بعد فعلي.');
S('push.denied', 'Notifications are blocked. Allow them in your browser/phone settings.', 'Notifications bloquées. Autorisez-les dans les réglages.', 'الإشعارات محظورة. اسمحي بها من الإعدادات.', 'الإشعارات مبلوكيين. سمحي ليهم من الإعدادات.');
